-- Sulmos26: independent empty installation. No shops, products, users, or example transactions are seeded.
CREATE TABLE IF NOT EXISTS business (id TEXT PRIMARY KEY CHECK (id='primary'), name TEXT NOT NULL, trading_name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', currency TEXT NOT NULL DEFAULT 'ZAR', vat_rate REAL NOT NULL DEFAULT 15, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','manager','sales','cashier','stock','dispatch','viewer')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (identifier TEXT PRIMARY KEY, attempts INTEGER NOT NULL, blocked_until TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stores (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE COLLATE NOCASE, address TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, sku TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, category TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', price_cents INTEGER NOT NULL DEFAULT 0 CHECK(price_cents>=0), cost_cents INTEGER NOT NULL DEFAULT 0 CHECK(cost_cents>=0), barcode TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_documents (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, type TEXT NOT NULL CHECK(type IN ('grv','count','adjustment','transfer','supplier_return')), store_id TEXT NOT NULL REFERENCES stores(id), destination_store_id TEXT REFERENCES stores(id), counterparty TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', lines_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','submitted','approved','rejected')) DEFAULT 'draft', created_by TEXT NOT NULL REFERENCES users(id), reviewed_by TEXT REFERENCES users(id), reviewed_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quotations (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, store_id TEXT NOT NULL REFERENCES stores(id), customer_name TEXT NOT NULL, customer_phone TEXT NOT NULL DEFAULT '', lines_json TEXT NOT NULL, total_cents INTEGER NOT NULL CHECK(total_cents>=0), status TEXT NOT NULL DEFAULT 'awaiting_payment' CHECK(status IN ('awaiting_payment','cancelled')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, store_id TEXT REFERENCES stores(id), title TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','done')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_stock_store ON stock_documents(store_id,created_at);
CREATE INDEX IF NOT EXISTS idx_quote_store ON quotations(store_id,created_at);
CREATE INDEX IF NOT EXISTS idx_audit_date ON audit_log(created_at);
CREATE TABLE IF NOT EXISTS user_stores (user_id TEXT NOT NULL REFERENCES users(id), store_id TEXT NOT NULL REFERENCES stores(id), PRIMARY KEY(user_id,store_id));
